def check(condition: bool, message: str) -> None:
    if not condition:
        raise ValueError(message)


def sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def text_sha(value: str) -> str:
    return hashlib.sha256(value.encode()).hexdigest()


def write_json(path: Path, value: object) -> None:
    with path.open("x") as stream:
        json.dump(value, stream, indent=2, sort_keys=True)
        stream.write("\n")


class Editor:
    def __init__(self, source: str):
        self.source = source
        self.edits: list[tuple[str, str]] = []

    def once(self, old: str, new: str) -> None:
        check(self.source.count(old) == 1, "Expected one transform site: " + repr(old))
        self.source = self.source.replace(old, new, 1)
        self.edits.append((old, new))

    def method(self, start: str, end: str, transform) -> None:
        check(self.source.count(start) == 1 and self.source.count(end) == 1, "Method boundaries are not unique")
        begin = self.source.index(start)
        finish = self.source.index(end, begin + len(start))
        old = self.source[begin:finish]
        self.once(old, transform(old))

    def verify_reverse(self, original: str) -> None:
        restored = self.source
        for old, new in reversed(self.edits):
            check(restored.count(new) == 1, "Transformed source site cannot be reversed uniquely")
            restored = restored.replace(new, old, 1)
        check(restored == original, "Whitelisted edits did not reverse to the exact preimage")


def instrument(source: str) -> tuple[str, dict[str, str], int]:
    editor = Editor(source)
    fields = "\tprivate final long qualifiedOwnerOrdinal;\n"
    fields += "".join("\tprivate long qualified" + name + ";\n" for name in COUNTERS)
    editor.once("\tprivate long weakMisses;\n", "\tprivate long weakMisses;\n" + fields)
    editor.once("\t\tthis.ledger = ledger;\n",
                "\t\tthis.ledger = ledger;\n\t\tqualifiedOwnerOrdinal = PublicationQualifiedAccounting.open();\n")

    ordinary_weak = """\t\t\t\tif (value == null) {
\t\t\t\t\tweakMisses++;
\t\t\t\t\tclear(index);
"""
    observed_ordinary_weak = """\t\t\t\tif (value == null) {
\t\t\t\t\tweakMisses++;
\t\t\t\t\tqualifiedOrdinaryWeak++;
\t\t\t\t\tclear(index);
\t\t\t\t\tlong factorWeakBefore = qualifiedFactorWeakTerminal;
\t\t\t\t\tValue factorValue = findFactor(index, id, rowSequence);
\t\t\t\t\tif (factorValue != null) {
\t\t\t\t\t\tqualifiedOrdinaryWeakRecovered++;
\t\t\t\t\t} else if (qualifiedFactorWeakTerminal == factorWeakBefore) {
\t\t\t\t\t\tqualifiedOrdinaryWeakTerminalOther++;
\t\t\t\t\t} else {
\t\t\t\t\t\tqualifiedJointWeakTerminal++;
\t\t\t\t\t}
\t\t\t\t\treturn factorValue;
"""
    editor.once(ordinary_weak, observed_ordinary_weak)
    old_witness = """\t\t\t\t} else {
\t\t\t\t\tclear(index);
\t\t\t\t}
\t\t\t}
\t\t\treturn findFactor(index, id, rowSequence);
"""
    new_witness = old_witness.replace("\t\t\t\t\tclear(index);",
                                      "\t\t\t\t\tqualifiedOrdinaryWitnessFailures++;\n\t\t\t\t\tclear(index);", 1)
    editor.once(old_witness, new_witness)
    editor.once("\tsynchronized void abandon(Object currentView, Object currentExposure) {\n",
                "\tsynchronized void abandon(Object currentView, Object currentExposure) {\n"
                "\t\tqualifiedAbandonCalls++;\n")

    def factor(method: str) -> str:
        change = Editor(method)
        change.once("\t\tif (value == null) {\n\t\t\tweakMisses++;\n",
                    "\t\tif (value == null) {\n\t\t\tweakMisses++;\n\t\t\tqualifiedFactorWeakTerminal++;\n")
        witness = ("\t\tif (!matches(page.versions[cell], page.revisionIds[cell], page.revisionOwners[cell], id, value)) {\n")
        change.once(witness, witness + "\t\t\tqualifiedFactorWitnessFailures++;\n")
        return change.source

    editor.method("\tprivate Value findFactor(", "\tprivate void rememberFactor(", factor)

    def refusal_returns(method: str, counter: str, expected: int) -> str:
        pattern = r"(?m)^(\t+)return null;\n"
        check(len(re.findall(pattern, method)) == expected, "Unexpected admission return sites for " + counter)
        return re.sub(pattern, lambda found: found[1] + "qualified" + counter + ";\n" + found[0], method)

    editor.method("\tprivate FactorPage admitFactorPage(", "\tprivate boolean resizeFactorDirectory(",
                  lambda method: refusal_returns(method, "FactorPageAdmissionRefusals++", 3))
    editor.method("\tprivate FactorMemo allocateFactorMemo(",
                  "\t/** Last validated coordinates for each target, invalidated by accumulated source-slot changes. */",
                  lambda method: refusal_returns(method, "FactorMemoAdmissionRefusals++", 2))

    def ordinary_admission(method: str) -> str:
        change = Editor(method)
        change.once("\t\tif (claim == null) {\n\t\t\tadmissionRefused = true;\n",
                    "\t\tif (claim == null) {\n\t\t\tadmissionRefused = true;\n"
                    "\t\t\tqualifiedOrdinaryAdmissionRefusals++;\n")
        return change.source

    editor.method("\tprivate boolean allocate(", "\tprivate void clearEntries(", ordinary_admission)
    close_tail = "\t\t\thitMasksInUse = false;\n\t\t}\n\t}\n}\n"
    observed_tail = """\t\t\thitMasksInUse = false;
\t\t\tPublicationQualifiedAccounting.close(qualifiedOwnerOrdinal, qualifiedOrdinaryWeak,
\t\t\t\t\tqualifiedOrdinaryWeakRecovered, qualifiedOrdinaryWeakTerminalOther, qualifiedJointWeakTerminal,
\t\t\t\t\tqualifiedFactorWeakTerminal, qualifiedOrdinaryWitnessFailures, qualifiedFactorWitnessFailures,
\t\t\t\t\tqualifiedAbandonCalls, qualifiedOrdinaryAdmissionRefusals, qualifiedFactorMemoAdmissionRefusals,
\t\t\t\t\tqualifiedFactorPageAdmissionRefusals);
\t\t}
\t}
}
"""
    editor.once(close_tail, observed_tail)
    editor.verify_reverse(source)
    generated = editor.source
    check(source.count(".get()") == generated.count(".get()"), "Materializer dereference count changed")
    check(source.count("new WeakReference") == generated.count("new WeakReference"), "Weak reference creation changed")
    check("System.gc(" not in generated and "ThreadLocal" not in generated, "Unexpected retention/GC mechanism")
    added_fields = re.findall(r"^\tprivate (?:final )?(.+) (qualified\w+);$", generated, flags=re.MULTILINE)
    check(len(added_fields) == 12 and all(kind == "long" for kind, _ in added_fields),
          "Observer fields must be exactly twelve primitive longs")
    weak_branch = generated[generated.index("\t\t\t\tif (value == null) {"):generated.index("\t\t\t\t} else if (matches")]
    check(weak_branch.count("findFactor(") == 1 and weak_branch.count("return factorValue;") == 1,
          "Ordinary weak branch must make exactly one factor lookup and return its result")

    regions = {}
    for name, start, end in (
        ("planAndImports", None, "/**\n * Evaluation-local last-value memo."),
        ("ordinaryPublication", "\tvoid remember(", "\tsynchronized void unbound("),
        ("coordinateCapture", "\tprivate boolean captureCoordinate(", "\tprivate Value findFactor("),
        ("factorPublication", "\tprivate void rememberFactor(", "\tprivate FactorPage memoPage("),
        ("factorMemoAndPage", "\tprivate static final class FactorMemo", "\tprivate boolean allocate("),
    ):
        def region(text: str) -> str:
            begin = text.index(start) if start is not None else 0
            return text[begin:text.index(end, begin)]

        before = region(source)
        check(before == region(generated), "Preserved source region changed: " + name)
        regions[name] = text_sha(before)
    return generated, regions, len(editor.edits)


def validate_red(folder: Path) -> tuple[Path, list[dict[str, str]]]:
    receipt_path = folder / "validation-receipt.json"
    receipt = json.loads(receipt_path.read_text())
    check(receipt["mode"] == "red" and receipt["passedStage"] and receipt["moduleSourcesUnchanged"],
          "Generator requires an accepted red-stage receipt")
    check(receipt["results"] == EXPECTED_RESULTS, "Wrong red-stage result counts")
    check(receipt["testSourceSha256"] == TEST_SOURCE_SHA and sha(TEST_SOURCE) == TEST_SOURCE_SHA,
          "Contract source changed from the accepted red stage")
    check(sha(folder / TEST_SOURCE.name) == TEST_SOURCE_SHA, "Archived red contract source changed")
    for key, filename in (
        ("resultsSha256", "results.json"),
        ("productionClassFilesSha256", "production-class-files.json"),
        ("testClassFilesSha256", "test-class-files.json"),
        ("executionClasspathManifestSha256", "execution-classpath-manifest.json"),
    ):
        check(sha(folder / filename) == receipt[key], "Changed red evidence file: " + filename)
    commands = json.loads((folder / "tests-command.json").read_text())
    check(commands["exit_code"] != 0, "Expected a genuinely failing red test process")
    reports = sorted((folder / "surefire-reports").glob("TEST-*.xml"))
    check(len(reports) == 1, "Wrong number of red XML reports")
    suite = ET.parse(reports[0]).getroot()
    check({key: int(suite.attrib[key]) for key in ("tests", "failures", "errors", "skipped")}
          == {key: EXPECTED_RESULTS[key] for key in ("tests", "failures", "errors", "skipped")},
          "Raw XML results do not match the red receipt")
    methods = set(re.findall(r"@Test\s+void\s+(\w+)\(", TEST_SOURCE.read_text()))
    seen = set()
    for case in suite.findall("testcase"):
        name = case.attrib["name"]
        check(name in methods and name not in seen, "Unexpected or duplicate red case")
        seen.add(name)
        check(case.find("error") is None and case.find("skipped") is None, "Red errors/skips are not evidence")
        failure = case.find("failure")
        if name == "disabledObserverLeavesActualResolutionAndCleanupIntact":
            check(failure is None, "Disabled observer contract must already pass")
        else:
            check(failure is not None and "qualified-observer:" in failure.attrib.get("message", ""),
                  "A real behavior/GC failure cannot authorize observer implementation")
    check(seen == methods and len(seen) == 15, "Missing red contract cases")
    class_map = json.loads((folder / "production-class-files.json").read_text())
    for name in ("NativeResultMaterializer.class", "NativeResultMaterializerPlan.class"):
        relative = (PACKAGE / name).as_posix()
        check(class_map[relative] == sha(BASE / "classes" / relative), "Red did not use the original publication overlay")
    paths = [receipt_path, folder / "results.json", folder / "tests-command.json", folder / TEST_SOURCE.name,
             folder / "production-class-files.json", folder / "test-class-files.json",
             folder / "execution-classpath-manifest.json", *reports]
    return receipt_path, [{"path": str(path), "sha256": sha(path)} for path in paths]


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--source", type=Path, default=SOURCE)
    parser.add_argument("--red-validation", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    source_path = args.source.resolve(strict=True)
    output = args.output.resolve()
    check(output.is_relative_to(HERE) and output != HERE, "Generated output must be beneath contracts")
    check(not output.exists(), "Refusing to overwrite a previous generation")
    check(sha(source_path) == SOURCE_SHA, "Generator requires the exact previous publication overlay")
    red_receipt, red_files = validate_red(args.red_validation.resolve(strict=True))
    original = source_path.read_text()
    generated, regions, edit_count = instrument(original)
    observer = OBSERVER.read_text()
    check("WeakReference" not in observer and "ThreadLocal" not in observer and "System.gc(" not in observer,
          "Observer may not inspect weak references or alter retention/GC")
    check("import " not in observer and "Value " not in observer and "NativeResult" not in observer,
          "Observer must not accept or retain query/value/coordinate objects")
    output.mkdir(parents=True)
    preimage = output / "preimage" / RELATIVE_SOURCE
    materializer = output / "src" / RELATIVE_SOURCE
    helper = output / "src" / RELATIVE_OBSERVER
    preimage.parent.mkdir(parents=True)
    materializer.parent.mkdir(parents=True)
    shutil.copyfile(source_path, preimage)
    materializer.write_text(generated)
    shutil.copyfile(OBSERVER, helper)
    patch = output / "accounting-overlay.patch"
    patch_text = "".join(difflib.unified_diff(original.splitlines(True), generated.splitlines(True),
                                            fromfile="a/src/" + RELATIVE_SOURCE.as_posix(),
                                            tofile="b/src/" + RELATIVE_SOURCE.as_posix()))
    patch_text += "".join(difflib.unified_diff([], observer.splitlines(True), fromfile="/dev/null",
                                             tofile="b/src/" + RELATIVE_OBSERVER.as_posix()))
    patch.write_text(patch_text)
    check(sha(source_path) == SOURCE_SHA and sha(preimage) == SOURCE_SHA, "Preimage changed while generating")
    receipt = {
        "format": 1, "stage": "generated-awaiting-compilation", "sourceFile": str(source_path),
        "sourceSha256": SOURCE_SHA, "generatedSourceFile": str(materializer),
        "generatedSourceSha256": sha(materializer), "observerSourceFile": str(helper),
        "observerSourceSha256": sha(helper), "generatorFile": str(Path(__file__).resolve()),
        "generatorSha256": sha(Path(__file__)), "sourcePatchFile": str(patch), "sourcePatchSha256": sha(patch),
        "redValidationReceiptFile": str(red_receipt), "redValidationReceiptSha256": sha(red_receipt),
        "redEvidenceFiles": red_files, "preservedRegions": regions, "whitelistedTransformSites": edit_count,
        "noExtraMaterializerGetCalls": True, "materializerGetCallCount": original.count(".get()"),
        "unchangedWeakReferenceCreationCount": original.count("new WeakReference"),
        "noProductionWrites": True, "javaLaunched": False, "addedMaterializerFields": 12,
        "addedMaterializerFieldTypes": "long only", "addedMaterializerFieldPayloadBytes": 96,
        "recordLongWords": 16, "recordLongPayloadBytes": 128, "recordCompletionSlots": "one boolean per owner",
        "normalObservationCapacity": 13, "normalRecordLongPayloadBytes": 1664,
        "observerLedgerAccounting": "Experimental field/buffer overhead is outside the unchanged query-ledger claims and common to every arm.",
        "scope": "Serial, non-reentrant native fixtures; weak fallback costs remain part of the natural-GC total effect.",
        "counters": [name[0].lower() + name[1:] for name in COUNTERS],
    }
    write_json(output / "source-receipt.json", receipt)
    print(json.dumps({"generated": str(output), "materializerSha256": sha(materializer),
                      "observerSha256": sha(helper), "redTests": 15, "javaLaunched": False}, indent=2))


if __name__ == "__main__":
    main()
